<?php

declare(strict_types=1);

namespace MSSTC4PHP\DtoCollectionGenerator\Application\Port;

use MSSTC4PHP\DtoCollectionGenerator\Domain\Spec\CollectionSpec;
use MSSTC4PHP\DtoCollectionGenerator\Domain\Target\TargetProfile;
use MSSTC4PHP\DtoCollectionGenerator\Domain\Validation\ClassFacts;

interface CodeEmitter
{
    /**
     * The first line after the opening tag of every generated file; the writer overwrites only files that start with it.
     */
    public const HEADER = '// @generated by msstc4php/dto-collection-generator — DO NOT EDIT';

    /**
     * @return string the whole file, ending in a newline
     */
    public function emit(CollectionSpec $spec, TargetProfile $target, ClassFacts $facts): string;
}
